// Generates lib/color_beats/levels_data.g.dart (500 levels, goals calibrated by robot play-tests).
// Run from packages/color_beats_game:  dart run tool/generate_levels.dart [count]
import 'dart:io';

import 'package:color_beats_game/color_beats/engine/level_gen.dart';

void main(List<String> args) {
  final count = args.isNotEmpty ? int.parse(args.first) : 500;
  final sw = Stopwatch()..start();
  final seen = <String>{};
  final pics = <String, int>{};
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/generate_levels.dart — do not edit by hand.',
    )
    ..writeln(
      '// Goals were calibrated by robot play-tests (most robot games win without help).',
    )
    ..writeln('// Board: 8 rows; . empty, 0-7 block color, a b c gem block.')
    ..writeln("import 'engine/level_gen.dart';")
    ..writeln()
    ..writeln('const levelData = <LevelData>[');
  for (var i = 0; i < count; i++) {
    final d = calibrate(i, seen);
    seen.add(d.signature);
    pics[d.picture] = (pics[d.picture] ?? 0) + 1;
    final board = d.board.map((r) => "'$r'").join(', ');
    out.writeln(
      "  LevelData(tier: ${d.tier}, lines: ${d.lines}, score: ${d.score}, picture: '${d.picture}', board: [$board]), // ${i + 1}",
    );
    if ((i + 1) % 50 == 0) {
      stdout.writeln(
        'levels ${i + 1}/$count  (${(sw.elapsedMilliseconds / 1000).toStringAsFixed(1)}s)',
      );
    }
  }
  out.writeln('];');
  File('lib/color_beats/levels_data.g.dart').writeAsStringSync(out.toString());
  stdout.writeln(
    'done in ${(sw.elapsedMilliseconds / 1000).toStringAsFixed(1)}s; pictures: $pics',
  );
}
